// Entry point: starts the Field Notes MCP server on 127.0.0.1:$PORT/mcp.

import type { AddressInfo } from "node:net";
import { FieldNotesHandlers } from "./handlers.js";
import { MCP_PATH, createMcpHttpServer } from "./http.js";
import { createSeededStore } from "./store.js";

const HOST = "127.0.0.1";
const requestedPort = Number(process.env.PORT ?? 3000);
if (!Number.isInteger(requestedPort) || requestedPort < 0 || requestedPort > 65535) {
  console.error(`Invalid PORT: ${process.env.PORT}`);
  process.exit(1);
}

const shutdown = new AbortController();
const server = createMcpHttpServer({
  handlers: new FieldNotesHandlers(createSeededStore()),
  shutdown: shutdown.signal,
  port: () => (server.address() as AddressInfo | null)?.port ?? requestedPort,
});

server.listen(requestedPort, HOST, () => {
  const { port } = server.address() as AddressInfo;
  console.error(`field-notes MCP server listening on http://${HOST}:${port}${MCP_PATH}`);
});

function stop(): void {
  if (shutdown.signal.aborted) return;
  // Ends open subscriptions gracefully and stops in-flight work.
  shutdown.abort(new Error("Server shutting down"));
  server.close(() => process.exit(0));
  setTimeout(() => {
    server.closeAllConnections();
    process.exit(0);
  }, 1000).unref();
}

process.on("SIGINT", stop);
process.on("SIGTERM", stop);

