describe("delete_note", () => {
  it("requires the form elicitation capability", async () => {
    for (const caps of [{}, { elicitation: { url: {} } }]) {
      const res = await callTool("delete_note", { id: "n1" }, { capabilities: caps });
      assert.equal(res.status, 400);
      assert.equal(res.json.error.code, -32021);
      assert.ok(res.json.error.data.requiredCapabilities.elicitation);
    }
  });

  it("reports a missing note as a tool error", async () => {
    const res = await callTool("delete_note", { id: "n999" }, { capabilities: FORM });
    assert.equal(res.json.result.isError, true);
    assert.equal(res.json.result.content[0].text, "Note n999 not found");
  });

  it("asks for confirmation, then deletes on accept with confirm: true", async () => {
    const first = await callTool("delete_note", { id: "n3" }, { capabilities: { elicitation: {} } });
    assert.equal(first.status, 200);
    const r = first.json.result;
    assert.equal(r.resultType, "input_required");
    assert.equal(typeof r.requestState, "string");
    const keys = Object.keys(r.inputRequests);
    assert.equal(keys.length, 1);
    const ask = r.inputRequests[keys[0]!];
    assert.equal(ask.method, "elicitation/create");
    assert.equal(ask.params.mode, "form");
    assert.equal(ask.params.message, 'Delete note "Groceries"?');
    assert.equal(ask.params.requestedSchema.properties.confirm.type, "boolean");
    assert.deepEqual(ask.params.requestedSchema.required, ["confirm"]);
    assert.equal(r.ttlMs, undefined);

    const retry = await callTool("delete_note", { id: "n3" }, { capabilities: FORM }, {
      inputResponses: { [keys[0]!]: { action: "accept", content: { confirm: true } } },
      requestState: r.requestState,
    });
    assert.equal(retry.json.result.resultType, "complete");
    assert.equal(retry.json.result.isError, false);
    assert.deepEqual(retry.json.result.content, [{ type: "text", text: "Deleted note n3" }]);
    assert.ok(!(await readIndex()).some((n) => n.id === "n3"));

    const gone = await rpc(server.port, "resources/read", { uri: "notes://notes/n3" });
    assert.equal(gone.json.error.code, -32602);
  });

  it("cancels on decline, cancel, or confirm: false", async () => {
    for (const answer of [
      { action: "decline" },
      { action: "cancel" },
      { action: "accept", content: { confirm: false } },
    ]) {
      const first = await callTool("delete_note", { id: "n1" }, { capabilities: FORM });
      const { inputRequests, requestState } = first.json.result;
      const key = Object.keys(inputRequests)[0]!;
      const retry = await callTool("delete_note", { id: "n1" }, { capabilities: FORM }, {
        inputResponses: { [key]: answer },
        requestState,
      });
      assert.equal(retry.json.result.resultType, "complete", JSON.stringify(answer));
      assert.equal(retry.json.result.isError, false);
      assert.deepEqual(retry.json.result.content, [{ type: "text", text: "Deletion cancelled" }]);
    }
    assert.ok((await readIndex()).some((n) => n.id === "n1"));
  });

  it("does not delete without a server-issued requestState", async () => {
    const res = await callTool("delete_note", { id: "n1" }, { capabilities: FORM }, {
      inputResponses: { confirm_delete: { action: "accept", content: { confirm: true } } },
    });
    assert.equal(res.json.result.resultType, "input_required");
    assert.ok((await readIndex()).some((n) => n.id === "n1"));
  });

  it("rejects a forged or modified requestState", async () => {
    const first = await callTool("delete_note", { id: "n1" }, { capabilities: FORM });
    const { inputRequests, requestState } = first.json.result;
    const key = Object.keys(inputRequests)[0]!;
    const [payload, sig] = requestState.split(".");
    const data = JSON.parse(Buffer.from(payload, "base64url").toString());
    const tampered = `${Buffer.from(JSON.stringify({ ...data, noteId: "n2" })).toString("base64url")}.${sig}`;
    for (const state of [tampered, "garbage", requestState + "x"]) {
      const res = await callTool("delete_note", { id: "n2" }, { capabilities: FORM }, {
        inputResponses: { [key]: { action: "accept", content: { confirm: true } } },
        requestState: state,
      });
      assert.ok(res.json.error, state);
      assert.equal(res.json.error.code, -32602);
    }
    const ids = (await readIndex()).map((n) => n.id);
    assert.ok(ids.includes("n1") && ids.includes("n2"));
  });

  it("does not let a confirmation for one note delete another", async () => {
    const first = await callTool("delete_note", { id: "n1" }, { capabilities: FORM });
    const { inputRequests, requestState } = first.json.result;
    const key = Object.keys(inputRequests)[0]!;
    const res = await callTool("delete_note", { id: "n2" }, { capabilities: FORM }, {
      inputResponses: { [key]: { action: "accept", content: { confirm: true } } },
      requestState,
    });
    assert.ok(res.json.error);
    assert.ok((await readIndex()).some((n) => n.id === "n2"));
  });

  it("asks again when the retry carries no answer", async () => {
    const first = await callTool("delete_note", { id: "n1" }, { capabilities: FORM });
    const res = await callTool("delete_note", { id: "n1" }, { capabilities: FORM }, {
      requestState: first.json.result.requestState,
    });
    assert.equal(res.json.result.resultType, "input_required");
  });
});

describe("reindex", () => {
  it("returns a plain JSON result without a progress token", async () => {
    const res = await callTool("reindex", { steps: 2, delayMs: 0 });
    assert.match(res.headers["content-type"]!, /^application\/json/);
    assert.deepEqual(res.json.result.content, [{ type: "text", text: "Reindex complete: 2 steps" }]);
  });

  it("uses defaults of 5 steps", async () => {
    const res = await callTool("reindex", { delayMs: 0 });
    assert.equal(res.json.result.content[0].text, "Reindex complete: 5 steps");
  });

  it("streams progress notifications before the result", async () => {
    const stream = openStream(server.port, "tools/call", { name: "reindex", arguments: { steps: 3, delayMs: 10 } }, {
      meta: { progressToken: "tok-1" },
    });
    await stream.ready;
    assert.equal(stream.status, 200);
    assert.match(stream.contentType, /^text\/event-stream/);
    const events = await stream.waitFor((evs) => evs.some((e) => "result" in e.data));
    const progress = events.filter((e) => e.data.method === "notifications/progress").map((e) => e.data.params);
    assert.deepEqual(progress, [
      { progressToken: "tok-1", progress: 1, total: 3, message: "Indexed 1/3" },
      { progressToken: "tok-1", progress: 2, total: 3, message: "Indexed 2/3" },
      { progressToken: "tok-1", progress: 3, total: 3, message: "Indexed 3/3" },
    ]);
    const last = events.at(-1)!.data;
    assert.equal(last.id, stream.id);
    assert.equal(last.result.content[0].text, "Reindex complete: 3 steps");
  });

  it("stops when the client disconnects", async () => {
    const stream = openStream(server.port, "tools/call", { name: "reindex", arguments: { steps: 20, delayMs: 100 } }, {
      meta: { progressToken: 42 },
    });
    await stream.waitFor((evs) => evs.length >= 1);
    stream.close();
    await sleep(50);
    // The server stays healthy after the cancelled request.
    const res = await rpc(server.port, "server/discover");
    assert.equal(res.status, 200);
  });

  it("reports out-of-range arguments as tool execution errors", async () => {
    for (const args of [{ steps: 0 }, { steps: 21 }, { steps: 2.5 }, { delayMs: -1 }, { delayMs: 1001 }, { steps: "3" }]) {
      const res = await callTool("reindex", args);
      assert.equal(res.json.result.isError, true, JSON.stringify(args));
    }
  });
});

