      { progressToken: "tok-1", progress: 1, total: 3, message: "Indexed 1/3" },
      { progressToken: "tok-1", progress: 2, total: 3, message: "Indexed 2/3" },
      { progressToken: "tok-1", progress: 3, total: 3, message: "Indexed 3/3" },
